<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><style>body{font-family:DejaVu Sans;direction:rtl}table{width:100%;border-collapse:collapse}td,th{padding:8px;border:1px solid #bbb}</style><body><h1>استفسار إجازة #{{$record->id}}</h1><table><tr><th>اسم المريض</th><td>{{$record->patient_name}}</td><th>الجنسية</th><td>{{$record->nationality}}</td></tr><tr><th>رقم الهوية</th><td>{{$record->idno}}</td><th>رقم الملف</th><td>{{$record->file_number}}</td></tr><tr><th>مدة الإجازة</th><td>{{$record->days}} أيام</td><th>جهة الإصدار</th><td>{{$record->issuer}}</td></tr><tr><th>تاريخ الإصدار</th><td>{{is_numeric($record->issue_date)?date('Y-m-d',(int)$record->issue_date):$record->issue_date}}</td><th>القرار</th><td>{{$record->manager_reply==1?'تمت الموافقة':($record->manager_reply==2?'مرفوض':'معلق')}} {{$record->manager_reply_reason}}</td></tr></table></body></html>
